import type { On } from 'claude-code'
import { PROJECT_REWRITER_NAMES } from './tools'

/** Files that mark a project generated by Tuist or XcodeGen, whose project file is regenerated. */
const GENERATOR_MARKERS = ['Project.swift', 'Workspace.swift', 'Tuist', 'project.yml']

const REASON =
  'xcrew: this project is generated (Tuist or XcodeGen), and XcodeWrite re-saves the whole generated project file. ' +
  'Create the file with the Write tool instead; the generator picks it up.'

/**
 * Refuses the Xcode MCP's file writer in generated projects only. In a classic Xcode project,
 * XcodeWrite is how a new file joins its target, so it stays allowed there.
 */
export function registerGuard(on: On): void {
  on('tool.call', { tool: PROJECT_REWRITER_NAMES }, async ($, e, next) => {
    const root = await $.session.root()
    const checks = await Promise.all(GENERATOR_MARKERS.map(marker => $.fs.exists(`${root}/${marker}`)))
    return checks.some(Boolean) ? { deny: REASON } : next(e)
  })
}
